8	const isSphinx = (card: Card): boolean => card.monster === SPHINX;
9	
10	const sum = (total: number, score: number): number => total + score;
11	
12	const countTypes = (army: Card[]): number =>
13	  new Set(army.map((card) => card.monster)).size;
