const BASE_SCORE = 2;
const TYPES_INCLUDED_IN_BASE_SCORE = 3;

const scoreSphinx = (army: Card[]): number => {
  const types = countDistinctTypes(army);
  const typesBeyondBase = Math.max(types - TYPES_INCLUDED_IN_BASE_SCORE, 0);
  return BASE_SCORE + typesBeyondBase;
};

